MATCH (fa:FlightAccident)-[:operatedBy]->(op:Operator)
WHERE fa.flight_number = '3603' OR fa.name = 'Aeroflot Flight 3603'
RETURN DISTINCT op.name AS Operator, op.country AS Country;

MATCH (fa:FlightAccident)-[:departsFrom]->(airport:Airport)
WHERE fa.name IN ["Sriwijaya Air Flight 182", "Adam Air Flight 574"]
RETURN DISTINCT airport.name AS airportName;

MATCH (m:AircraftModel)-[:manufacturedBy]->(am:AircraftManufacturer)
WHERE am.name = "PZL Mielec"
RETURN m.name AS model_name, m.wingspan_metre AS wingspan_in_meters;

MATCH (fa:FlightAccident)-[:departsFrom]->(ap:Airport)
WHERE toUpper(fa.flight_number) CONTAINS 'SA201'
RETURN ap.name AS AirportName, fa.flight_number AS FlightNumber;

MATCH (m:AircraftManufacturer)
WHERE m.name =~ '.*Novosibirsk Aircraft Production Association.*'
RETURN m.country AS country;

MATCH (f1:FlightAccident {name: 'Tatarstan Airlines Flight 363'}), (f2:FlightAccident {name: 'Mandala Airlines Flight 091'})
RETURN f1.number_of_injuries AS injuries_f1, f2.number_of_injuries AS injuries_f2,
       toInteger(f1.number_of_injuries) = toInteger(f2.number_of_injuries) AS equal_injuries;

MATCH (boac:FlightAccident {name: "BOAC Flight 911"})-[:destinedFor]->(dest:Airport)
MATCH (acc:FlightAccident)-[:departsFrom]->(dest)
RETURN DISTINCT acc.name AS accidentName;

MATCH (fa:FlightAccident)-[:involves]->(am:AircraftModel), (fa)-[:departsFrom]->(dep:Airport)
WHERE am.name CONTAINS 'Airbus A300' OR any(alias IN am.aliases WHERE alias CONTAINS 'Airbus A300')
RETURN DISTINCT dep.name AS airport_name;
